//! 🌐️ Whole-model selection, atomic product records and failed-product rollback share one original index.
use super::*;
impl GeometryPreparationCursor{
 fn append_metadata(&mut self,issues:bool,value:[u32;3],turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{if self.work>=self.request.limits.work{return Err("preparation-work-limit")}let pages=if issues{self.issues.as_mut().unwrap()}else{self.records.as_mut().unwrap()};let before_work=pages.work();let before_bytes=pages.allocated_bytes();let result=pages.append_funded(value,turn,64,self.request.limits.result_bytes-self.result_bytes);self.work+=pages.work()-before_work;self.result_bytes+=pages.allocated_bytes()-before_bytes;result}
 pub(super) fn model_step<G:GeometryGraph>(&mut self,read:&CapturedGeometryRead<'_,G>,turn:&mut PreparationTurn<'_,'_>)->Result<(),&'static str>{match self.phase{
  PreparationPhase::Relationships=>{if !self.admit(turn,128,0,0,1)?{return Ok(())}if self.relationship==read.graph.len(){self.phase=PreparationPhase::Selecting;self.probe=None;return Ok(())}let relation=read.graph.entity(self.relationship).ok_or("preparation-missing-source-entity")?;if relation.name!="IFCRELVOIDSELEMENT"{self.relationship+=1;return Ok(())}if self.relationship_host==0{self.relationship_host=relation.args.get(4).and_then(GeometryValue::as_reference).ok_or("preparation-invalid-opening-relation")?;}let probe=*self.probe.get_or_insert((hash(self.relationship_host)as usize)&(self.slots-1));let existing=self.entry(probe);if existing.id==0{return Err("preparation-missing-opening-host")}if existing.id!=self.relationship_host{self.probe=Some((probe+1)%self.slots);return Ok(())}self.pages.as_mut().unwrap()[probe/PAGE_SLOTS][probe%PAGE_SLOTS].ordinal|=1<<63;self.probe=None;self.relationship_host=0;self.relationship+=1;Ok(())},
  PreparationPhase::Selecting=>{if !self.admit(turn,512,0,0,1)?{return Ok(())}if self.selection==read.graph.len(){self.phase=PreparationPhase::Ready;return Ok(())}let ordinal=self.selection;self.selection+=1;let entity=read.graph.entity(ordinal).ok_or("preparation-missing-source-entity")?;if !super::super::product::is_geometry_product(read.graph.standard(),entity.name)||entity.args.get(6).is_none_or(GeometryValue::is_unset){return Ok(())}self.target=entity.id;self.product_ordinal=ordinal;self.vertex_start=self.points.as_ref().map_or(0,mesh::RetainedMeshPages::len);self.triangle_start=self.triangles.as_ref().map_or(0,mesh::RetainedMeshPages::len);self.emitted=0;self.emission_pending=false;self.record_phase=0;self.representation_ordinal=0;if matches!(entity.name,"IFCOPENINGELEMENT"|"IFCOPENINGSTANDARDCASE"){self.reason=Some("opening-is-a-void-volume");self.issue_kind=4;self.phase=PreparationPhase::Retiring}else{self.phase=PreparationPhase::Projecting;self.push(Frame::new(1,entity.id))?;}Ok(())},
  PreparationPhase::Retiring=>{if self.points.as_ref().is_some_and(|pages|pages.len()>self.vertex_start){let pages=self.points.as_mut().unwrap();let before=pages.work();let result=pages.truncate_one(self.vertex_start,turn);self.work+=pages.work()-before;result?;return Ok(())}if self.triangles.as_ref().is_some_and(|pages|pages.len()>self.triangle_start){let pages=self.triangles.as_mut().unwrap();let before=pages.work();let result=pages.truncate_one(self.triangle_start,turn);self.work+=pages.work()-before;result?;return Ok(())}if self.issues.is_none(){if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<u32>>(),0,0,1)?{self.issues=Some(mesh::RetainedMeshPages::new(read.graph.len().min(u32::MAX as usize),self.request.limits.result_bytes)?)}return Ok(())}let ordinal=u32::try_from(self.product_ordinal).map_err(|_|"preparation-source-index-limit")?;let representation=u32::try_from(self.representation_ordinal).map_err(|_|"preparation-source-index-limit")?;if self.append_metadata(true,[ordinal,self.issue_kind,representation],turn)?{self.issue_count+=1;self.reason=None;self.phase=PreparationPhase::Selecting}Ok(())},
  PreparationPhase::Publishing=>{if self.records.is_none(){if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<u32>>(),0,0,1)?{self.records=Some(mesh::RetainedMeshPages::new(read.graph.len().saturating_mul(2).min(u32::MAX as usize),self.request.limits.result_bytes)?)}return Ok(())}let raw=if self.record_phase==0{[self.product_ordinal,self.representation_ordinal,self.vertex_start]}else{[self.points.as_ref().unwrap().len()-self.vertex_start,self.triangle_start,self.triangles.as_ref().unwrap().len()-self.triangle_start]};let mut row=[0;3];for axis in 0..3{row[axis]=u32::try_from(raw[axis]).map_err(|_|"preparation-source-index-limit")?;}if self.append_metadata(false,row,turn)?{self.record_phase+=1;if self.record_phase==2{self.record_count+=1;self.phase=PreparationPhase::Selecting}}Ok(())},
  _=>Err("preparation-invalid-model-frontier")
 }}
 pub fn prepared_count<G:GeometryGraph>(&self,read:&CapturedGeometryRead<'_,G>)->Result<usize,&'static str>{self.check_source(read)?;Ok(if self.phase!=PreparationPhase::Ready{0}else if matches!(self.request.scope,PreparationScope::Model){self.record_count}else{1})}
 pub fn issue_count<G:GeometryGraph>(&self,read:&CapturedGeometryRead<'_,G>)->Result<usize,&'static str>{self.check_source(read)?;Ok(if self.phase==PreparationPhase::Ready{self.issue_count}else{0})}
 pub fn issue<G:GeometryGraph>(&self,read:&CapturedGeometryRead<'_,G>,index:usize)->Result<Option<(u64,&'static str)>,&'static str>{self.check_source(read)?;if self.phase!=PreparationPhase::Ready||index>=self.issue_count{return Ok(None)}let pages=self.issues.as_ref().unwrap();let ordinal=pages.get(index,0)?as usize;let kind=pages.get(index,1)?;let entity=read.graph.entity(ordinal).ok_or("preparation-product-source-missing")?;Ok(Some((entity.id,match kind{2=>"preparation-unsupported-product",3=>"preparation-opening-frontier-not-implemented",4=>"opening-is-a-void-volume",_=>"preparation-invalid-product"})))}
}
